    14→/* ============================================================
    15→   Chunk Management
    16→   ============================================================ */
    17→
    18→Chunk* chunk_new(void) {
    19→    Chunk* chunk = (Chunk*)malloc(sizeof(Chunk));
    20→    if (!chunk) return NULL;
    21→
    22→    chunk->code_capacity = 256;
    23→    chunk->code = (uint8_t*)malloc(chunk->code_capacity);
    24→    if (!chunk->code) {
    25→        free(chunk);
    26→        return NULL;
    27→    }
    28→    chunk->code_len = 0;
    29→
    30→    chunk->const_capacity = 32;
    31→    chunk->consts = (fl_value_t*)malloc(chunk->const_capacity * sizeof(fl_value_t));
    32→    if (!chunk->consts) {
    33→        free(chunk->code);
    34→        free(chunk);
    35→        return NULL;
    36→    }
    37→    chunk->const_len = 0;
    38→
    39→    chunk->locals_count = 0;
    40→    chunk->line_map = NULL;
    41→    chunk->line_map_capacity = 0;
    42→
    43→    return chunk;
    44→}
    45→
    46→void chunk_free(Chunk* chunk) {
    47→    if (!chunk) return;
    48→    if (chunk->code) free(chunk->code);
    49→    if (chunk->consts) free(chunk->consts);
    50→    if (chunk->line_map) free(chunk->line_map);
    51→    free(chunk);
    52→}
    53→
    54→void chunk_emit_opcode(Chunk* chunk, fl_opcode_t opcode) {
    55→    if (!chunk) return;
    56→
    57→    if (chunk->code_len >= chunk->code_capacity) {
    58→        chunk->code_capacity *= 2;
    59→        uint8_t* new_code = (uint8_t*)realloc(chunk->code, chunk->code_capacity);
    60→        if (!new_code) return;
    61→        chunk->code = new_code;
    62→    }
    63→
    64→    chunk->code[chunk->code_len++] = (uint8_t)opcode;
    65→}
    66→
    67→int chunk_emit_int(Chunk* chunk, fl_int value) {
    68→    if (!chunk) return -1;
    69→
    70→    if (chunk->const_len >= chunk->const_capacity) {
    71→        chunk->const_capacity *= 2;
    72→        fl_value_t* new_consts = (fl_value_t*)realloc(chunk->consts, chunk->const_capacity * sizeof(fl_value_t));
    73→        if (!new_consts) return -1;
    74→        chunk->consts = new_consts;
    75→    }
    76→
    77→    int idx = chunk->const_len;
    78→    chunk->consts[idx].type = FL_TYPE_INT;
    79→    chunk->consts[idx].data.int_val = value;
    80→    chunk->const_len++;

